import{_ as o,o as a,c as n,a1 as s}from"./chunks/framework.Ccs17H5l.js";const h=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md"}'),t={name:"guide/configuration.md"};function i(r,e,l,c,p,d){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Once your project is created, it will be preconfigured to work right out of the box.</p><p>However, there are several things you need to know in order to customize your project.</p><h2 id="name" tabindex="-1">Name <a class="header-anchor" href="#name" aria-label="Permalink to &quot;Name&quot;">​</a></h2><p>To change the name of your project, it is very simple: you just need to change the <code>name</code> field under <code>[package]</code> in the <code>Cargo.toml</code> file:</p><div class="language-toml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#F44747;">...</span></span>
<span class="line"><span style="color:#D4D4D4;">[package]</span></span>
<span class="line highlighted"><span style="color:#9CDCFE;">name</span><span style="color:#D4D4D4;"> = </span><span style="color:#CE9178;">&quot;my_apa&quot;</span></span>
<span class="line"><span style="color:#9CDCFE;">version</span><span style="color:#D4D4D4;"> = </span><span style="color:#CE9178;">&quot;0.1.0&quot;</span></span>
<span class="line"><span style="color:#9CDCFE;">edition</span><span style="color:#D4D4D4;"> = </span><span style="color:#CE9178;">&quot;2024&quot;</span></span>
<span class="line"><span style="color:#F44747;">...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>The rest of the <code>Cargo.toml</code> file is preconfigured to work with your project&#39;s utilities. It is not recommended to modify it unless you know what you are doing.</p><h2 id="eadkp" tabindex="-1">.eadkp/ <a class="header-anchor" href="#eadkp" aria-label="Permalink to &quot;.eadkp/&quot;">​</a></h2><p>The <code>.eadkp/</code> folder mainly contains script and configuration files. <strong>You must not modify, delete, or move these files.</strong> The scripts are downloaded locally to work offline. They are updated by the update script and will be restored in case of deletion or modification.</p><p>The <code>config.env</code> file basically contains the configuration for the update script of your project&#39;s utilities. It is not recommended to change it unless you know what you are doing.</p><h2 id="justfile" tabindex="-1">justfile <a class="header-anchor" href="#justfile" aria-label="Permalink to &quot;justfile&quot;">​</a></h2><p>The provided <code>justfile</code> (an equivalent to a Makefile) only contains the import of the basic commands provided in <code>.eadkp/</code>: <code>export</code>, <code>build</code>, <code>sim</code>, etc.</p><p>It is here, following the import, that you can add your own custom commands, or even overwrite the basic commands if you wish.</p>`,13)])])}const m=o(t,[["render",i]]);export{h as __pageData,m as default};
